/*
 * Cooperative scheduler periods.
 *
 * The main loop has no RTOS. Instead, it calls short tasks when their elapsed
 * time has expired. Measurement/protection runs fastest; MPPT runs slower so
 * the converter can settle after a duty change; telemetry is rate-limited so
 * UART printing does not dominate the control loop.
 */
#define FAST_TASK_PERIOD_MS        (1U)
#define MPPT_TASK_PERIOD_MS        (50U)
#define TELEMETRY_TASK_PERIOD_MS   (50U)  /* 20 telemetry packets per second */
#define STARTUP_SETTLE_TIME_MS     (500U)



/* USER CODE END PD */

/* Private macro -------------------------------------------------------------*/
/* USER CODE BEGIN PM */

/* USER CODE END PM */

/* Private variables ---------------------------------------------------------*/

/* USER CODE BEGIN PV */

extern volatile bool mppt_start_requested;
extern volatile bool stop_requested;
extern volatile bool fault_reset_requested;

static uint32_t mppt_state_entered_ms;
static uint32_t fast_task_last_ms;
static uint32_t mppt_task_last_ms;
static uint32_t telemetry_task_last_ms;

volatile State_t state = STATE_INIT;
volatile Fault_t mppt_fault = FAULT_NONE;

/* USER CODE END PV */

/* Private function prototypes -----------------------------------------------*/
void SystemClock_Config(void);
/* USER CODE BEGIN PFP */

void setState(State_t next_state);
bool runFastTasks(void);
void MpptController_Task(void);
void controllerInit(void);



