/**
  * @brief  The application entry point.
  * @retval int
  */
int main(void)
{

  /* USER CODE BEGIN 1 */

  /* USER CODE END 1 */

  /* MCU Configuration--------------------------------------------------------*/

  /* Reset of all peripherals, Initializes the Flash interface and the Systick. */
  HAL_Init();

  /* USER CODE BEGIN Init */

  /* USER CODE END Init */

  /* Configure the system clock */
  SystemClock_Config();

  /* USER CODE BEGIN SysInit */

  /* USER CODE END SysInit */

  /* Initialize all configured peripherals */
  MX_GPIO_Init();
  MX_ADC1_Init();
  MX_ADC2_Init();
  MX_TIM1_Init();
  MX_USART1_UART_Init();
  MX_USART2_UART_Init();
  MX_TIM16_Init();
  MX_TIM3_Init();
  /* USER CODE BEGIN 2 */
  IrradianceSensor_Init();
  TemperatureSensor_Init();

  /* Start the PC console first so boot messages and fault states are visible. */
  SerialConsole_Init();
  SerialConsole_PrintBootMessage();

  /* Initialise the converter controller. This keeps the power stage disabled,
   * calibrates the ADCs, captures current-sensor offsets, and then enters IDLE. */
  controllerInit();
  SerialConsole_PrintStatus();
  /* USER CODE END 2 */

  /* Infinite loop */
  /* USER CODE BEGIN WHILE */
    /*
      * Cooperative super-loop.
      *
      * There is no operating system here. Each task must return quickly so the
      * next task can run on time. Avoid long blocking delays inside this loop.
      */

  while (1)
  {
    /* USER CODE END WHILE */

    /* USER CODE BEGIN 3 */
    const uint32_t now_ms = HAL_GetTick();

    /* Runs measurement, protection, state transitions, and MPPT updates. */
    #if 1
    

    /* Fast task: refresh measurements and perform simple feedback validity checks. */
    if (Timebase_HasElapsed(now_ms, fast_task_last_ms, FAST_TASK_PERIOD_MS))
    {
      fast_task_last_ms = now_ms;
      (void)runFastTasks();
    }

    /* Handle console commands after the safety-critical measurement checks. */
    SerialConsole_Task();

    switch ((State_t)state)
    {
      case STATE_INIT:
        /* If the controller ever reaches INIT after boot, return to a safe idle state. */
        setState(STATE_IDLE);
        break;

      case STATE_IDLE:
        /* IDLE is the safe waiting state. A start request is accepted only when
        * the latest ADC readings are valid and not saturated. */
        if (mppt_start_requested)
        {
          mppt_start_requested = false;
          if (Measurements_AreInAdcRange(Measurements_GetLatest()))
          {
            setState(STATE_MPPT_STARTUP);
          }
          else
          {
            const Measurements_t *measurements = Measurements_GetLatest();
            const Fault_t acquisition_fault = Measurements_GetAcquisitionFault();
            if (!measurements->valid)
            {
              enterFault((acquisition_fault != FAULT_NONE) ? acquisition_fault
                                                           : FAULT_ADC_READ);
            }
            else
            {
              enterFault(FAULT_ADC_RANGE);
            }
          }
        }
        break;

      case STATE_MPPT_STARTUP:
        /* STARTUP applies a small known duty command and waits for the converter
        * to settle before handing control to the student MPPT algorithm. */
        if (stop_requested)
        {
          stop_requested = false;
          setState(STATE_IDLE);
        }
        else if (Timebase_HasElapsed(now_ms, mppt_state_entered_ms, STARTUP_SETTLE_TIME_MS))
        {
          setState(STATE_MPPT_RUN);
        }
        break;

      case STATE_MPPT_RUN:
        /* RUN executes the MPPT algorithm at a medium rate. The duty cycle is not
        * updated every loop iteration, because the power stage and ADC readings
        * need time to respond after each command change. */
        if (stop_requested)
        {
          stop_requested = false;
          setState(STATE_IDLE);
          break;
        }

        if (Timebase_HasElapsed(now_ms, mppt_task_last_ms, MPPT_TASK_PERIOD_MS))
        {
          mppt_task_last_ms = now_ms;
          MpptController_Update();
        }

        break;

      case STATE_FAULT:
      default:
        /* FAULT is latched. Keep switching disabled until a deliberate reset request. */
        PowerStage_Disable();
        if (fault_reset_requested)
        {
          fault_reset_requested= false;
          stop_requested = false;
          mppt_start_requested = false;
          mppt_fault = FAULT_NONE;
          /* Rebuild the complete measurement chain instead of merely clearing
           * the visible fault and immediately tripping again on a stopped DMA. */
          controllerInit();
        }
        break;
    }
    #endif

    /* Sensor tasks only advance their state machines and never wait in the loop. */
    TemperatureSensor_Task();
    IrradianceSensor_Task();

    /* Queue telemetry after control and sensor state have been serviced. */
    if (Timebase_HasElapsed(now_ms, telemetry_task_last_ms, TELEMETRY_TASK_PERIOD_MS))
    {
      telemetry_task_last_ms = now_ms;
      Telemetry_Task();
    }

    /* Test-only status indication on LD3/PB3. See the warning in the function. */
    StatusLed_Task(state);
  }
  /* USER CODE END 3 */
}

