//Change to converter initialisation
void controllerInit(void)
{
  Fault_t acquisition_fault;

  /* The first firmware action for the converter controller is always safe output. */
  PowerStage_Disable();

  /* Calibration requires disabled ADCs. This is also the cleanup path when a
   * deliberate fault reset restarts acquisition after a DMA/ADC failure. */
  Measurements_StopSynchronized();

  /* ADC calibration compensates internal ADC errors before readings are trusted. */
  if (HAL_ADCEx_Calibration_Start(&hadc1, ADC_SINGLE_ENDED) != HAL_OK)
  {
    enterFault(FAULT_ADC1_CALIBRATION);
    return;
  }
  if (HAL_ADCEx_Calibration_Start(&hadc2, ADC_SINGLE_ENDED) != HAL_OK)
  {
    enterFault(FAULT_ADC2_CALIBRATION);
    return;
  }

  /* Arm both independent DMA streams before TIM1 starts their shared CC3 trigger.
   * The helper waits for complete buffers and publishes the first measurement. */
  acquisition_fault = Measurements_StartSynchronized();
  if (acquisition_fault != FAULT_NONE)
  {
    enterFault(acquisition_fault);
    return;
  }

  /* Store the no-load current-sensor levels from PWM-synchronised samples. */
  Measurements_CaptureZeroCurrentOffsets();

  /* Re-read after offset capture so converted current values use the new offsets. */
  if (!Measurements_Update())
  {
    acquisition_fault = Measurements_GetAcquisitionFault();
    enterFault((acquisition_fault != FAULT_NONE) ? acquisition_fault
                                                 : FAULT_ADC_READ);
    return;
  }
  setState(STATE_IDLE);
}

/**
  * @brief  Enters a new converter state and performs the required entry action.
  * @param  next_state State to enter.
  */
void setState(State_t next_state)
{
  state = next_state;
  mppt_state_entered_ms = HAL_GetTick();

  switch (next_state)
  {
    case STATE_INIT:
    case STATE_IDLE:
      /* In non-switching states, force the converter outputs to the safe state. */
      PowerStage_Disable();
      break;

    case STATE_MPPT_STARTUP:
      MpptController_Startup();
      break;

    case STATE_MPPT_RUN:
      /* RUN keeps the PWM hardware enabled. MpptController_Update() later changes compare values. */
      if (!PowerStage_Enable())
      {
        enterFault(FAULT_PWM_START);
      }
      break;

    case STATE_FAULT:
    default:
      /* Any unknown state is treated as a fault-like condition. */
      PowerStage_Disable();
      break;
  }
}

void requestMpptStart(void)
{
  mppt_start_requested = true;
  stop_requested = false;
}

void requestStop(void)
{
  stop_requested = true;
  mppt_start_requested = false;
}

void requestFaultReset(void)
{
  fault_reset_requested= true;
}

State_t getState(void)
{
  return (State_t)state;
}

Fault_t getFault(void)
{
  return (Fault_t)mppt_fault;
}

/**
  * @brief  Latches the fault reason and immediately moves the converter to FAULT.
  * @param  fault Fault code to store for debugging or telemetry.
  */
void enterFault(Fault_t fault)
{
  /* Store the cause before changing state so it can be printed and debugged. */
  mppt_fault = fault;
  setState(STATE_FAULT);
}

/**
  * @brief  Runs high-rate measurement and protection checks.
  * @retval true when fast tasks completed without tripping a fault.
  */
bool runFastTasks(void)
{
  const State_t current_state = (State_t)state;

  /* A failed ADC update means the controller no longer knows the converter state. */
  if (!Measurements_Update())
  {
    if (current_state != STATE_FAULT)
    {
      const Fault_t acquisition_fault = Measurements_GetAcquisitionFault();
      enterFault((acquisition_fault != FAULT_NONE) ? acquisition_fault
                                                   : FAULT_ADC_READ);
      return false;
    }

    return false;
  }

  /* Saturated ADC values are treated as invalid feedback while switching is active. */
  if (((current_state == STATE_MPPT_STARTUP) || (current_state == STATE_MPPT_RUN)) &&
      !Measurements_AreInAdcRange(Measurements_GetLatest()))
  {
    enterFault(FAULT_ADC_RANGE);
    return false;
  }

  return true;
}



